3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmButton } from '../../atoms/zimmButton';
5	import { ZimmMediaTile } from '../../atoms/zimmMediaTile';
6	import type { ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
7	import { getDesktopLayoutCounts } from './getDesktopLayoutCounts';
8	
9	const messages = defineMessages({
10	  openGallery: { id: 'product_gallery.trigger.open', defaultMessage: 'Open image gallery' },
11	  openGalleryAt: {
12	    id: 'product_gallery.trigger.open_at',
13	    defaultMessage: 'Open image gallery, image {index} of {total}',
14	  },
15	  galleryButton: { id: 'product_gallery.trigger.label', defaultMessage: 'Gallery +{count}' },
16	  // No confirmed Figma frame for this state yet (SFCC-731 AC 1/2/4's plain button, counts of
17	  // 3/4/6) — reasoned default pending sign-off, same as the layout counts in
18	  // getDesktopLayoutCounts.ts.
19	  galleryButtonPlain: { id: 'product_gallery.trigger.label_plain', defaultMessage: 'Gallery' },
20	  goToSlide: { id: 'product_gallery.dot.label', defaultMessage: 'Go to image {index} of {total}' },
21	  currentSlide: { id: 'product_gallery.live.current', defaultMessage: '{alt}. Image {index} of {total}.' },
22	});
23	
24	const ZIMM_PRODUCT_GALLERY_RECIPE = 'ZimmProductGallery';
25	
26	// Item-count layout (which items stack vs grid, grid row width) lives in
27	// getDesktopLayoutCounts.ts, per SFCC-731's Acceptance Criteria. Only the grid's own column
28	// count is needed here, for chunking gridItems into rows.
29	const DESKTOP_GRID_COLUMNS = 2;
30	
31	// SFCC-731 AC 19 — DIS responsive widths per tile type. `base: '100vw'` everywhere below `lg`
32	// (every tile is full-bleed there); the `lg` ceiling is each tile type's own Figma reference
33	// width (zimmMediaTile.css.ts's own comment: stacked 902px, grid 450px) — a fluid column can
34	// render slightly under this on an ultra-wide viewport, which is a fine trade-off against
35	// shipping full raw resolution unconditionally.
36	const STACKED_ITEM_WIDTHS = { base: '100vw', lg: 902 };
37	const GRID_ITEM_WIDTHS = { base: '100vw', lg: 450 };
38	const COMPACT_ITEM_WIDTHS = { base: '100vw' };
39	
40	// ZimmMediaTile (ui-kits/atoms) owns the canonical media-item shape now — re-exported here so
41	// existing importers of this module (product-view/mapImageGroupsToGalleryMedia.ts, this
42	// component's own stories/tests) don't need to change their import path.
43	export type { ZimmGalleryPhotoItem, ZimmGalleryVideoItem, ZimmGalleryMediaItem } from '../../atoms/zimmMediaTile';
44	
45	type ZimmProductGalleryProps = {
46	  /** Ordered photo/video sequence. Video renders as a positional slot only — see ZimmGalleryVideoItem. */
47	  media: ZimmGalleryMediaItem[];
48	  /**
